// Variables: const no se puede reasignar, let sí. (Evitá var.)
const equipo = 'Plataforma';
let pendientes = 3;
pendientes = pendientes - 1;

// Objeto: datos agrupados con nombre
const tarea = { id: 1, titulo: 'Configurar CI', hecha: false };
console.log(tarea.titulo);   // 'Configurar CI'

// Array: lista ordenada
const tareas = [
  { id: 1, titulo: 'Configurar CI', hecha: false },
  { id: 2, titulo: 'Login con JWT', hecha: true },
];

// Función flecha
const saludar = (nombre) => `Hola, ${nombre}`;   // template string con ${ }

// map: transforma cada elemento y devuelve un array NUEVO
const titulos = tareas.map((t) => t.titulo);       // ['Configurar CI', 'Login con JWT']

// filter: se queda con los que cumplen la condición
const sinTerminar = tareas.filter((t) => !t.hecha); // [{ id: 1, ... }]

// spread: copiar y agregar sin modificar el original
const conNueva = [...tareas, { id: 3, titulo: 'Dockerizar', hecha: false }];
const editada = { ...tarea, hecha: true };

